<template>
  <a-table class="similar-products-row"
           slot="expandedRowRender"
           :columns="columns"
           :data-source="comparisons"
           :pagination="false">
    <div slot="cost" slot-scope="cost, record">
      {{
        record.cost ? formatCostInPence2dp({
          cost: record.cost,
          cost_currency: 'USD'
        }) : '-'
      }}
    </div>
    <div slot="savings" slot-scope="savings, record">
      <span :class="{'text-danger': record.savings < 0}">{{
          record.cost ? formatCostInPence2dp({
            cost: record.savings,
            cost_currency: 'USD'
          }) : '-'
        }}</span>
      <a-tag style="margin-left: 15px;" color="blue">P&L</a-tag>
    </div>
  </a-table>
</template>

<script>
import Dates from "../../../../mixins/Dates";
import Orders from "../../../../mixins/Orders";

const columns = [
  {
    title: 'Comparison',
    dataIndex: 'comparison'
  },
  {
    title: 'Cost',
    dataIndex: 'cost',
    key: 'cost',
    scopedSlots: {customRender: 'cost'}
  },
  {
    title: 'Savings',
    dataIndex: 'savings',
    key: 'savings',
    scopedSlots: {customRender: 'savings'}
  }
];
export default {
  name: "SavingsSummary",
  props: ['row'],
  mixins: [Dates, Orders],
  data() {
    return {
      columns
    }
  },
  computed: {
    benchmarkPrice() {
      let prices = _.map(this.row.prices, 'price');
      let average = _.mean(prices) * 1.3;
      return average;
    },

    comparisons() {
      let comparisons = [
        {
          comparison: 'Benchmark',
          cost: this.benchmarkPrice,
          savings: this.row.selectedPrice ? (this.benchmarkPrice - this.row.selectedPrice.price) : 0
        }
      ];

      if (this.row.order) {
        comparisons.push({
          comparison: 'Exact Match',
          cost: this.row.order.cost,
          savings: (this.benchmarkPrice - this.row.order.cost)
        });
      }

      return comparisons;
    }
  }
}
</script>

